// CXS_CCIX_Stream_Interface_apb: APB4 register wrapper around CXS_CCIX_Stream_Interface_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/CXS_CCIX_Stream_Interface.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/CXS_CCIX_Stream_Interface.md
// ============================================================================
module CXS_CCIX_Stream_Interface_apb #(
  parameter int RXF = 4
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic cxs_tx_valid,
  output logic [127:0] cxs_tx_data,
  output logic [13:0] cxs_tx_cntl,
  input logic cxs_tx_crdgnt,
  output logic cxs_tx_crdrtn,
  output logic cxs_tx_activereq,
  input logic cxs_tx_activeack,
  input logic cxs_tx_deacthint,
  input logic cxs_rx_valid,
  input logic [127:0] cxs_rx_data,
  input logic [13:0] cxs_rx_cntl,
  output logic cxs_rx_crdgnt,
  input logic cxs_rx_crdrtn,
  input logic cxs_rx_activereq,
  output logic cxs_rx_activeack,
  output logic cxs_rx_deacthint
);
  localparam logic [31:0] ID_VALUE = 32'h43580200;

  // ---------------- core ----------------
  logic          c_tx_en;
  logic          c_rx_en;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [31:0]   c_tx_data;
  logic          c_tx_last;
  logic          c_tx_err;
  logic          c_rx_valid;
  logic          c_rx_ready;
  logic [31:0]   c_rx_data;
  logic          c_rx_last;
  logic          c_rx_err;
  logic [1:0]    c_tx_link;
  logic [1:0]    c_rx_link;
  logic [3:0]    c_tx_credits;
  logic          c_ev_crd;
  logic          c_ev_cntl;
  CXS_CCIX_Stream_Interface_top #(.RXF(RXF)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .tx_en(c_tx_en),
    .rx_en(c_rx_en),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_data(c_tx_data),
    .tx_last(c_tx_last),
    .tx_err(c_tx_err),
    .rx_valid(c_rx_valid),
    .rx_ready(c_rx_ready),
    .rx_data(c_rx_data),
    .rx_last(c_rx_last),
    .rx_err(c_rx_err),
    .cxs_tx_valid(cxs_tx_valid),
    .cxs_tx_data(cxs_tx_data),
    .cxs_tx_cntl(cxs_tx_cntl),
    .cxs_tx_crdgnt(cxs_tx_crdgnt),
    .cxs_tx_crdrtn(cxs_tx_crdrtn),
    .cxs_tx_activereq(cxs_tx_activereq),
    .cxs_tx_activeack(cxs_tx_activeack),
    .cxs_tx_deacthint(cxs_tx_deacthint),
    .cxs_rx_valid(cxs_rx_valid),
    .cxs_rx_data(cxs_rx_data),
    .cxs_rx_cntl(cxs_rx_cntl),
    .cxs_rx_crdgnt(cxs_rx_crdgnt),
    .cxs_rx_crdrtn(cxs_rx_crdrtn),
    .cxs_rx_activereq(cxs_rx_activereq),
    .cxs_rx_activeack(cxs_rx_activeack),
    .cxs_rx_deacthint(cxs_rx_deacthint),
    .tx_link(c_tx_link),
    .rx_link(c_rx_link),
    .tx_credits(c_tx_credits),
    .ev_crd(c_ev_crd),
    .ev_cntl(c_ev_cntl)
  );

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [10:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd11) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- registers ----------------
  logic [4:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [1:0] r_CTRL;   // 12'h014 CTRL
  logic [31:0] h_TX0;   // 12'h018 TX0 holding register
  logic [1:0] h_TX1;   // 12'h01C TX1 holding register
  logic [31:0] h_RX0;   // 12'h020 RX0 holding register
  logic [1:0] h_RX1;   // 12'h024 RX1 holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 2'h0;
      h_TX0 <= '0;
      h_TX1 <= '0;
      h_RX0 <= '0;
      h_RX1 <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[4:0] & wmask[4:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[6] && !full_TX) h_TX0 <= (h_TX0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7] && !full_TX) h_TX1 <= (h_TX1 & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[7] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[9]))) begin
        h_RX0[31:0] <= c_rx_data[31:0];
        h_RX1[0:0] <= c_rx_last;
        h_RX1[1:1] <= c_rx_err;
        avail_RX <= 1'b1;
      end else if (rd && hit[9]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_tx_en = r_CTRL[0:0];
  assign c_rx_en = r_CTRL[1:1];
  assign c_tx_data[31:0] = h_TX0[31:0];
  assign c_tx_last = h_TX1[0:0];
  assign c_tx_err = h_TX1[1:1];
  assign c_tx_valid = full_TX;
  assign c_rx_ready = ~avail_RX | (rd & hit[9]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_ev_crd;
    irq_set[1] = c_ev_cntl;
    irq_set[2] = full_TX & c_tx_ready;
    irq_set[3] = wr & (hit[6] | hit[7]) & full_TX;
    irq_set[4] = c_rx_valid & (~avail_RX | (rd & hit[9]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd3: rdata = 32'(flags);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(r_CTRL);
      10'd6: rdata = 32'(h_TX0);
      10'd7: rdata = 32'(h_TX1);
      10'd8: rdata = 32'(h_RX0);
      10'd9: rdata = 32'(h_RX1);
      10'd10: rdata = 32'({c_tx_credits, c_rx_link, c_tx_link});
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
